  nd = rs + rz + rz -> 65536 < nd -> 4096 * (q - 1) < nd <= 4096 * q ->
  (* [comment removed for export] *)
  0x10007fff8000 + 4096 <= sp -> sp + 2144 <= 2 ^ 47 ->
  4096 <= t -> t + 4096 < 2 ^ 47 -> (t + 4096 <= 0x10000 \/ 0x69c000 <= t) -> apart t 4096 (sp - 1952) 6048 -> apart t 4096 0x7fff8000 0x100000000000 ->
  apart ctx 4096 (sp - 1952) 6048 -> (ctx + 4096 <= 0x10000 \/ 0x69c000 <= ctx) -> apart t 4096 ctx 4096 -> apart ctx 4096 0x7fff8000 0x100000000000 ->
  0 <= loff -> 0x10100 <= tp -> tp + 8 <= 0x69c000 -> 0x10000 <= tp + loff -> tp + loff + 4 <= 0x69c000 -> 0x10000 <= tsd -> tsd + 1024 <= 0x69c000 ->
  ab mod 4096 = 0 -> 0x69c000 + 4096 <= ab -> (ab + 4096 * q < 0x7fff8000 \/ 0x10007fff8000 + 4096 <= ab) -> ab + 4096 * q < 2 ^ 47 ->
  apart (ab - 4096) (4096 * q + 4096) (sp - 1952) 6048 -> apart (ab - 4096) (4096 * q + 4096) t 4096 -> apart (ab - 4096) (4096 * q + 4096) ctx 4096 ->
  0 <= spb -> spb + 2 ^ 37 < 2 ^ 48 -> (ab < spb \/ spb + 2 ^ 37 <= ab) ->
  0 <= id < 2 ^ 32 -> 0 <= b1 < 256 ->
  0 <= f120 < 2 ^ 64 -> 0 <= f112 < 2 ^ 64 -> 0 <= f104 < 2 ^ 64 -> 0 <= f96 < 2 ^ 64 -> 0 <= f88 < 2 ^ 64 -> 0 <= f80 < 2 ^ 64 -> 0 <= f72 < 2 ^ 64 ->
